/* CommerceForge Dev Docs - Global Styles */

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --bg-card: rgba(22, 27, 34, 0.8);
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #f0f6fc;
  --text-secondary: #8b949e;
  --text-muted: #484f58;
  --accent-blue: #475F91;
  --accent-cyan: #39d0d8;
  --accent-green: #3fb950;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --sidebar-width: 280px;
  --sidebar-collapsed: 64px;
  --header-height: 64px;
  --radius: 12px;
  --radius-sm: 8px;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-primary);
}
::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* Typography */
h1, h2, h3, h4 {
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.02em;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
  transition: color var(--transition);
}
a:hover {
  color: var(--accent-cyan);
}

/* Header */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 32px;
}

.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent-blue);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  color: white;
}

.main-nav {
  display: flex;
  gap: 24px;
}

.main-nav a {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 500;
  padding: 6px 0;
  position: relative;
}

.main-nav a:hover,
.main-nav a.active {
  color: var(--text-primary);
}

.main-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-blue);
  border-radius: 2px;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.search-btn,
.theme-toggle {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
}

.search-btn:hover,
.theme-toggle:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.login-btn {
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
}

.login-btn:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

/* Mobile menu toggle */
.mobile-menu-toggle {
  display: none;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

/* Layout with sidebar */
.page-layout {
  display: flex;
  min-height: 100vh;
  padding-top: var(--header-height);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-subtle);
  position: fixed;
  top: var(--header-height);
  left: 0;
  bottom: 0;
  overflow-y: auto;
  transition: width var(--transition);
  z-index: 100;
}

.sidebar.collapsed {
  width: var(--sidebar-collapsed);
}

.sidebar-header {
  padding: 16px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
}

.sidebar-title {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
}

.sidebar.collapsed .sidebar-title {
  opacity: 0;
}

.collapse-btn {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  flex-shrink: 0;
}

.collapse-btn:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.sidebar.collapsed .collapse-btn {
  transform: rotate(180deg);
}

.sidebar-nav {
  padding: 12px 0;
}

.sidebar-section {
  margin-bottom: 8px;
}

.sidebar-section-title {
  padding: 8px 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
}

.sidebar.collapsed .sidebar-section-title {
  opacity: 0;
}

.sidebar-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 20px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  transition: all var(--transition);
  white-space: nowrap;
  overflow: hidden;
}

.sidebar-link:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.sidebar-link.active {
  background: rgba(71, 95, 145, 0.15);
  color: var(--accent-blue);
  border-right: 2px solid var(--accent-blue);
}

.sidebar-link i {
  font-size: 1.125rem;
  width: 24px;
  text-align: center;
  flex-shrink: 0;
}

.sidebar.collapsed .sidebar-link span,
.sidebar.collapsed .sidebar-section-title {
  opacity: 0;
  width: 0;
}

.main-content {
  flex: 1;
  margin-left: var(--sidebar-width);
  transition: margin-left var(--transition);
  min-width: 0;
}

.sidebar.collapsed + .main-content {
  margin-left: var(--sidebar-collapsed);
}

/* Sections */
.section {
  padding: 80px 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.section-sm {
  padding: 60px 24px;
}

.section-title {
  font-size: 2rem;
  margin-bottom: 12px;
  color: var(--text-primary);
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin-bottom: 48px;
}

/* Hero */
.hero {
  padding: 100px 24px 80px;
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
}

.hero-title {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 700;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-secondary);
  max-width: 720px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}

.btn-primary:hover {
  background: #3a4f7a;
  color: white;
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  background: var(--border-color);
  color: white;
}

.btn-ghost {
  background: transparent;
  color: var(--accent-blue);
  padding: 8px 0;
}

.btn-ghost:hover {
  color: var(--accent-cyan);
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.card-grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
}

.card-grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.card-grid-4 {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.card {
  background: var(--card-bg, var(--bg-card));
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 32px;
  transition: all var(--transition);
  backdrop-filter: blur(10px);
}

.card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: rgba(71, 95, 145, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--accent-blue);
  margin-bottom: 20px;
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: 8px;
  color: var(--text-primary);
}

.card-text {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 20px;
  line-height: 1.6;
}

.card-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent-blue);
  font-size: 0.9375rem;
  font-weight: 500;
}

.card-cta:hover {
  color: var(--accent-cyan);
}

/* Product cards specific */
.product-card {
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent-blue);
  opacity: 0;
  transition: opacity var(--transition);
}

.product-card:hover::before {
  opacity: 1;
}

/* CLI Section */
.cli-section {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.cli-header {
  text-align: center;
  margin-bottom: 48px;
}

.cli-header .section-subtitle {
  margin-left: auto;
  margin-right: auto;
}

.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  margin-bottom: 12px;
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item:hover {
  border-color: var(--text-muted);
}

.accordion-item.active {
  border-color: var(--accent-blue);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  transition: background var(--transition);
}

.accordion-header:hover {
  background: var(--bg-tertiary);
}

.accordion-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 12px;
}

.accordion-title i {
  color: var(--accent-blue);
  font-size: 1.25rem;
}

.accordion-chevron {
  color: var(--text-muted);
  transition: transform var(--transition);
}

.accordion-item.active .accordion-chevron {
  transform: rotate(180deg);
  color: var(--accent-blue);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition), padding var(--transition);
}

.accordion-item.active .accordion-body {
  max-height: 600px;
  padding: 0 24px 24px;
}

.accordion-steps {
  margin-bottom: 20px;
}

.accordion-step {
  display: flex;
  gap: 16px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-subtle);
}

.accordion-step:last-child {
  border-bottom: none;
}

.step-number {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(71, 95, 145, 0.2);
  color: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
}

.step-text {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  padding-top: 2px;
}

/* Code block */
.code-block {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--code-border);
  background: var(--bg-tertiary);
}

.code-tab {
  padding: 10px 18px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: none;
  background: transparent;
  transition: all var(--transition);
  font-family: inherit;
}

.code-tab:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.code-tab.active {
  color: var(--accent-cyan);
  background: var(--code-bg);
  border-bottom: 2px solid var(--accent-cyan);
  margin-bottom: -1px;
}

.code-content {
  padding: 16px 20px;
  font-family: 'JetBrains Mono', 'Fira Code', 'SF Mono', Monaco, monospace;
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--text-primary);
  overflow-x: auto;
}

.code-content pre {
  margin: 0;
}

.code-content .comment {
  color: var(--text-muted);
}

.code-content .keyword {
  color: #ff7b72;
}

.code-content .string {
  color: #a5d6ff;
}

.code-content .command {
  color: var(--accent-green);
}

.code-panel {
  display: none;
}

.code-panel.active {
  display: block;
}

/* Launch CTA */
.launch-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--accent-blue);
}

.launch-card h3 {
  font-size: 1.125rem;
  margin-bottom: 8px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 16px;
}

/* Community */
.community-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
}

.community-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  transition: all var(--transition);
  color: var(--text-primary);
}

.community-card:hover {
  border-color: var(--accent-blue);
  transform: translateY(-2px);
}

.community-card i {
  font-size: 1.5rem;
  color: var(--accent-blue);
}

.community-card span {
  font-weight: 500;
  font-size: 0.9375rem;
}

/* Footer */
.site-footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  padding: 60px 24px 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto 48px;
}

.footer-column h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-column ul {
  list-style: none;
}

.footer-column li {
  margin-bottom: 10px;
}

.footer-column a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-column a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 24px;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 20px;
}

.footer-legal a {
  color: var(--text-muted);
  font-size: 0.8125rem;
}

/* Interior page hero */
.page-hero {
  padding: 60px 24px 40px;
  max-width: 900px;
  margin: 0 auto;
}

.page-hero-title {
  font-size: clamp(2rem, 4vw, 2.75rem);
  margin-bottom: 12px;
}

.page-hero-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
}

/* Interior sections */
.interior-section {
  padding: 48px 24px;
  max-width: 900px;
  margin: 0 auto;
}

.interior-section + .interior-section {
  border-top: 1px solid var(--border-subtle);
}

.interior-section h2 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.interior-section h2 i {
  color: var(--accent-blue);
}

.interior-section h3 {
  font-size: 1.125rem;
  margin: 24px 0 12px;
  color: var(--text-primary);
}

.interior-section p {
  color: var(--text-secondary);
  margin-bottom: 16px;
  line-height: 1.7;
}

.interior-section ul {
  list-style: none;
  padding: 0;
}

.interior-section li {
  padding: 8px 0;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.interior-section li::before {
  content: '›';
  color: var(--accent-blue);
  font-weight: 700;
  flex-shrink: 0;
}

/* Feature grid for interior pages */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
  margin-top: 24px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--text-muted);
}

.feature-card h4 {
  font-size: 1rem;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.feature-card h4 i {
  color: var(--accent-blue);
  font-size: 1.125rem;
}

.feature-card p {
  font-size: 0.875rem;
  margin-bottom: 0;
}

/* Protocol diagram */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin: 32px 0;
}

.protocol-actor {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px 20px;
  text-align: center;
  transition: all var(--transition);
}

.protocol-actor:hover {
  border-color: var(--accent-blue);
  transform: translateY(-2px);
}

.protocol-actor i {
  font-size: 2rem;
  color: var(--accent-blue);
  margin-bottom: 12px;
  display: block;
}

.protocol-actor h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.protocol-actor p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin: 0;
}

/* Coming soon badge */
.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.badge-soon {
  background: rgba(57, 208, 216, 0.15);
  color: var(--accent-cyan);
  border: 1px solid rgba(57, 208, 216, 0.3);
}

/* Support categories */
.support-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.support-card:hover {
  border-color: var(--accent-blue);
}

.support-card h4 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.875rem;
  margin-bottom: 0;
}

/* No sidebar pages */
.no-sidebar .main-content {
  margin-left: 0;
}

/* Responsive */
@media (max-width: 768px) {
  .main-nav {
    display: none;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-subtle);
    flex-direction: column;
    padding: 16px 24px;
    gap: 4px;
  }

  .main-nav.open {
    display: flex;
  }

  .main-nav a {
    padding: 10px 0;
  }

  .mobile-menu-toggle {
    display: flex;
  }

  .sidebar {
    transform: translateX(-100%);
    width: var(--sidebar-width) !important;
  }

  .sidebar.open {
    transform: translateX(0);
  }

  .sidebar.collapsed {
    transform: translateX(-100%);
  }

  .main-content {
    margin-left: 0 !important;
  }

  .card-grid,
  .card-grid-2,
  .card-grid-3,
  .card-grid-4 {
    grid-template-columns: 1fr;
  }

  .feature-grid {
    grid-template-columns: 1fr;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .btn {
    width: 100%;
    justify-content: center;
    max-width: 320px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .section {
    padding: 48px 16px;
  }

  .hero {
    padding: 80px 16px 48px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

/* Overlay for mobile sidebar */
.sidebar-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 99;
}

.sidebar-overlay.active {
  display: block;
}
